// Obtenir la date du jour au format DD/MM/YYYY (fuseau Europe/Paris)
const now = new Date();
const todayStr = now.toLocaleDateString('fr-FR', {
  timeZone: 'Europe/Paris',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});
// toLocaleDateString fr-FR retourne DD/MM/YYYY

// Filtrer les lignes dont la date = aujourd'hui ET Statut = 'À publier'
const filtered = items.filter(item => {
  const rowDate = (item.json['Date'] || '').trim();
  const statut = (item.json['Statut'] || '').trim();
  return rowDate === todayStr && statut === 'À publier';
});

if (filtered.length === 0) {
  // Aucun article à publier aujourd'hui — arrêter proprement
  return [];
}

return filtered;

// Construire le corps de la requête Claude pour cet article
const item = $input.item.json;
const titre = item['Titre'] || item['titre'] || '';
const categorie = item['Catégorie'] || item['categorie'] || '';

const systemPrompt = `Tu es un expert en rédaction SEO française spécialisé dans les parcs canins d'agility et les équipements pour collectivités. Tu rédiges pour Woof!, une marque de Herkules Fitness, leader européen des équipements de parcs canins depuis plus de 20 ans, présent dans plus de 500 communes en Europe.

Ton audience : élus locaux, directeurs des services techniques, responsables des espaces verts et de la voirie dans les mairies et intercommunalités françaises.

Règles de rédaction SEO :
- Longueur cible : 1400-1800 mots
- Structure : 1 introduction accrocheuse (2-3 phrases), 4-6 sections H2 avec des H3 si besoin, 1 conclusion avec appel à l'action
- Ton : expert, rassurant, institutionnel mais accessible
- Intégrer naturellement les mots-clés du titre et leurs variantes sémantiques (LSI)
- Inclure des listes à puces pour améliorer la lisibilité et le scanning
- Citer des chiffres ou données concrètes si pertinent (entretien, budget, réglementation)
- Mentionner naturellement Woof! et Herkules Fitness 2-3 fois dans le corps du texte
- Dernier paragraphe : appel à l'action pour demander un devis gratuit sur woof-parcs.fr
- Format : Markdown compatible MDX
- Ne PAS inclure de frontmatter YAML
- Ne PAS inclure de titre H1 (déjà géré par le frontmatter)`;

const userMessage = `Rédige un article de blog SEO complet sur le sujet suivant : ${titre}

Catégorie : ${categorie}

L'article doit :
1. Apporter une vraie valeur informative aux collectivités et mairies
2. Couvrir les aspects pratiques : choix des équipements, réglementation, budget, entretien si pertinent
3. Utiliser le champ lexical du sujet pour couvrir les requêtes associées
4. Intégrer naturellement des références à Woof! et Herkules Fitness
5. Terminer par un paragraphe d'appel à l'action invitant à demander un devis gratuit

Commence directement par l'introduction, sans titre H1.`;

const requestBody = {
  model: 'claude-opus-4-6',
  max_tokens: 4096,
  system: systemPrompt,
  messages: [
    {
      role: 'user',
      content: userMessage
    }
  ]
};

return [{
  json: {
    ...item,
    claudeRequestBody: JSON.stringify(requestBody)
  }
}];

// Récupérer les données du Sheet (depuis le noeud de préparation)
const sheetData = $('Préparer requête Claude').item.json;
const claudeResponse = $input.item.json;

// Extraire le contenu généré par Claude
let content = '';
try {
  content = claudeResponse.content[0].text;
} catch(e) {
  throw new Error('Réponse Claude invalide : ' + JSON.stringify(claudeResponse));
}

const titre = sheetData['Titre'] || '';
const categorie = sheetData['Catégorie'] || '';
const imageUrl = sheetData['Image URL'] || '';
const date = sheetData['Date'] || '';
const rowNumber = sheetData['row_number'] || '';

// Convertir date DD/MM/YYYY → YYYY-MM-DD pour le frontmatter
const parts = date.split('/');
const isoDate = parts.length === 3 ? `${parts[2]}-${parts[1]}-${parts[0]}` : date;

// Générer le slug URL à partir du titre
const slug = titre
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '') // supprimer accents
  .replace(/['']/g, '')
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-');

// Générer la meta description depuis le début du contenu
const cleanContent = content
  .replace(/^#{1,6}\s.+\n/gm, '') // supprimer les titres
  .replace(/\*\*([^*]+)\*\*/g, '$1') // supprimer le gras
  .replace(/\n+/g, ' ')
  .trim();
const description = cleanContent.length > 157
  ? cleanContent.substring(0, 157) + '...'
  : cleanContent;

// Construire le fichier MDX complet
const titleEscaped = titre.replace(/"/g, "'");
const descEscaped = description.replace(/"/g, "'");
const imgAltEscaped = titre.replace(/"/g, "'");

const mdx = `---
title: "${titleEscaped}"
description: "${descEscaped}"
pubDate: ${isoDate}
image: "${imageUrl}"
imageAlt: "${imgAltEscaped}"
category: "${categorie}"
---

${content}`;

// Encoder en base64 pour l'API GitHub
const mdxBase64 = Buffer.from(mdx, 'utf-8').toString('base64');

return [{
  json: {
    slug,
    mdxBase64,
    titre,
    date,
    isoDate,
    rowNumber,
    categorie,
    imageUrl
  }
}];
